static Map<Long, Set<String>> acl = Map.of(42L, Set.of("alice"));
static Map<Long, Boolean> decisions = new HashMap<>();

static boolean canView(String user, long docId) {
    return decisions.computeIfAbsent(docId,
            id -> acl.getOrDefault(id, Set.of()).contains(user));
}

System.out.println(canView("bob", 42) + " " + canView("alice", 42) + " " + canView("bob", 42));
